import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start, both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [
    ['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}],
  ]);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: false });
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const r = await h.inFlight();
  assert.deepEqual(r.map((m) => [m.from, m.to, m.action, m.data]), [['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('one fails twice, other completes', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0'); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true });
});

test('a retried task can complete', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  const m = await h.inFlight();
  await h.deliver(m[0].id);
  assert.deepEqual((await h.inFlight()).map((x) => [x.from, x.to, x.action]), [['run', 'worker0', 'Assign']]);
  await h.deliverAll();
  await h.workDone('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false });
});

test('a failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
});

test('cancel after one completed', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const m = await h.inFlight();
  assert.deepEqual(m.map((x) => [x.to, x.action]), [['worker1', 'Abort']]);
  assert.equal((await h.run()).status, 'cancelling');
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', retried0: false, retried1: false });
});

test('timeout fails a task and aborts its worker', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual((await h.inFlight()).map((x) => [x.to, x.action]), [['worker0', 'Abort']]);
